macro_rules! deps {
    () => {
        ParseStream!();
        Result!();
        Parse!();
    };
}

macro_rules! Speculative {
    () => {
        deps!();
        # [doc = " Extensions to the `ParseStream` API to support speculative parsing."] pub trait Speculative { # [doc = " Advance this parse stream to the position of a forked parse stream."] # [doc = ""] # [doc = " This is the opposite operation to [`ParseStream::fork`]. You can fork a"] # [doc = " parse stream, perform some speculative parsing, then join the original"] # [doc = " stream to the fork to \"commit\" the parsing from the fork to the main"] # [doc = " stream."] # [doc = ""] # [doc = " If you can avoid doing this, you should, as it limits the ability to"] # [doc = " generate useful errors. That said, it is often the only way to parse"] # [doc = " syntax of the form `A* B*` for arbitrary syntax `A` and `B`. The problem"] # [doc = " is that when the fork fails to parse an `A`, it's impossible to tell"] # [doc = " whether that was because of a syntax error and the user meant to provide"] # [doc = " an `A`, or that the `A`s are finished and it's time to start parsing"] # [doc = " `B`s. Use with care."] # [doc = ""] # [doc = " Also note that if `A` is a subset of `B`, `A* B*` can be parsed by"] # [doc = " parsing `B*` and removing the leading members of `A` from the"] # [doc = " repetition, bypassing the need to involve the downsides associated with"] # [doc = " speculative parsing."] # [doc = ""] # [doc = " [`ParseStream::fork`]: ParseBuffer::fork"] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " There has been chatter about the possibility of making the colons in the"] # [doc = " turbofish syntax like `path::to::<T>` no longer required by accepting"] # [doc = " `path::to<T>` in expression position. Specifically, according to [RFC"] # [doc = " 2544], [`PathSegment`] parsing should always try to consume a following"] # [doc = " `<` token as the start of generic arguments, and reset to the `<` if"] # [doc = " that fails (e.g. the token is acting as a less-than operator)."] # [doc = ""] # [doc = " This is the exact kind of parsing behavior which requires the \"fork,"] # [doc = " try, commit\" behavior that [`ParseStream::fork`] discourages. With"] # [doc = " `advance_to`, we can avoid having to parse the speculatively parsed"] # [doc = " content a second time."] # [doc = ""] # [doc = " This change in behavior can be implemented in syn by replacing just the"] # [doc = " `Parse` implementation for `PathSegment`:"] # [doc = ""] # [doc = " ```"] # [doc = " # use syn::ext::IdentExt;"] # [doc = " use syn::parse::discouraged::Speculative;"] # [doc = " # use syn::parse::{Parse, ParseStream};"] # [doc = " # use syn::{Ident, PathArguments, Result, Token};"] # [doc = ""] # [doc = " pub struct PathSegment {"] # [doc = "     pub ident: Ident,"] # [doc = "     pub arguments: PathArguments,"] # [doc = " }"] # [doc = " #"] # [doc = " # impl<T> From<T> for PathSegment"] # [doc = " # where"] # [doc = " #     T: Into<Ident>,"] # [doc = " # {"] # [doc = " #     fn from(ident: T) -> Self {"] # [doc = " #         PathSegment {"] # [doc = " #             ident: ident.into(),"] # [doc = " #             arguments: PathArguments::None,"] # [doc = " #         }"] # [doc = " #     }"] # [doc = " # }"] # [doc = ""] # [doc = " impl Parse for PathSegment {"] # [doc = "     fn parse(input: ParseStream) -> Result<Self> {"] # [doc = "         if input.peek(Token![super])"] # [doc = "             || input.peek(Token![self])"] # [doc = "             || input.peek(Token![Self])"] # [doc = "             || input.peek(Token![crate])"] # [doc = "         {"] # [doc = "             let ident = input.call(Ident::parse_any)?;"] # [doc = "             return Ok(PathSegment::from(ident));"] # [doc = "         }"] # [doc = ""] # [doc = "         let ident = input.parse()?;"] # [doc = "         if input.peek(Token![::]) && input.peek3(Token![<]) {"] # [doc = "             return Ok(PathSegment {"] # [doc = "                 ident,"] # [doc = "                 arguments: PathArguments::AngleBracketed(input.parse()?),"] # [doc = "             });"] # [doc = "         }"] # [doc = "         if input.peek(Token![<]) && !input.peek(Token![<=]) {"] # [doc = "             let fork = input.fork();"] # [doc = "             if let Ok(arguments) = fork.parse() {"] # [doc = "                 input.advance_to(&fork);"] # [doc = "                 return Ok(PathSegment {"] # [doc = "                     ident,"] # [doc = "                     arguments: PathArguments::AngleBracketed(arguments),"] # [doc = "                 });"] # [doc = "             }"] # [doc = "         }"] # [doc = "         Ok(PathSegment::from(ident))"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " # syn::parse_str::<PathSegment>(\"a<b,c>\").unwrap();"] # [doc = " ```"] # [doc = ""] # [doc = " # Drawbacks"] # [doc = ""] # [doc = " The main drawback of this style of speculative parsing is in error"] # [doc = " presentation. Even if the lookahead is the \"correct\" parse, the error"] # [doc = " that is shown is that of the \"fallback\" parse. To use the same example"] # [doc = " as the turbofish above, take the following unfinished \"turbofish\":"] # [doc = ""] # [doc = " ```text"] # [doc = " let _ = f<&'a fn(), for<'a> serde::>();"] # [doc = " ```"] # [doc = ""] # [doc = " If this is parsed as generic arguments, we can provide the error message"] # [doc = ""] # [doc = " ```text"] # [doc = " error: expected identifier"] # [doc = "  --> src.rs:L:C"] # [doc = "   |"] # [doc = " L | let _ = f<&'a fn(), for<'a> serde::>();"] # [doc = "   |                                    ^"] # [doc = " ```"] # [doc = ""] # [doc = " but if parsed using the above speculative parsing, it falls back to"] # [doc = " assuming that the `<` is a less-than when it fails to parse the generic"] # [doc = " arguments, and tries to interpret the `&'a` as the start of a labelled"] # [doc = " loop, resulting in the much less helpful error"] # [doc = ""] # [doc = " ```text"] # [doc = " error: expected `:`"] # [doc = "  --> src.rs:L:C"] # [doc = "   |"] # [doc = " L | let _ = f<&'a fn(), for<'a> serde::>();"] # [doc = "   |               ^^"] # [doc = " ```"] # [doc = ""] # [doc = " This can be mitigated with various heuristics (two examples: show both"] # [doc = " forks' parse errors, or show the one that consumed more tokens), but"] # [doc = " when you can control the grammar, sticking to something that can be"] # [doc = " parsed LL(3) and without the LL(*) speculative parsing this makes"] # [doc = " possible, displaying reasonable errors becomes much more simple."] # [doc = ""] # [doc = " [RFC 2544]: https://github.com/rust-lang/rfcs/pull/2544"] # [doc = " [`PathSegment`]: crate::PathSegment"] # [doc = ""] # [doc = " # Performance"] # [doc = ""] # [doc = " This method performs a cheap fixed amount of work that does not depend"] # [doc = " on how far apart the two streams are positioned."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " The forked stream in the argument of `advance_to` must have been"] # [doc = " obtained by forking `self`. Attempting to advance to any other stream"] # [doc = " will cause a panic."] fn advance_to (& self , fork : & Self) ; }
    };
}

Speculative!()